  {
    "path": "/examples/master-system/sms-opll-instruments.js",
    "name": "sms-opll-instruments",
    "data": "// Master System: built-in YM2413 instruments. No patch or sample upload needed.\nsetBpm(120);\nopll.setVoice(0, {attenuation: 5, sustain: false});\n\nliveLoop('sms-opll-instruments', async () => {\n  for (const instrument of [1, 2, 3, 4, 8, 12, 14, 15]) {\n    opll.setInstrument(0, instrument);\n    log(instrument, OPLL_INSTRUMENTS[instrument]);\n    for (const note of ['C4', 'E4', 'G4', 'C5']) {\n      opll.noteOn(0, note);\n      await beat(0.35);\n      opll.keyOff(0);\n      await beat(0.15);\n    }\n  }\n});\n\n// Instrument 0 is the one shared User patch; instruments 1..15 are fixed ROM.\n"
  },
  {
    "path": "/examples/master-system/sms-opll-rhythm.js",
    "name": "sms-opll-rhythm",
    "data": "// Master System: six melodic FM channels plus five hardware rhythm voices.\nsetBpm(120);\nopll.setNote(6, 'C2'); // Bass drum tuning uses physical CH6.\nopll.setNote(7, 'G3'); // Hi-hat / snare share physical CH7.\nopll.setNote(8, 'D3'); // Tom / cymbal share physical CH8.\nopll.setRhythm({enabled: true});\nopll.setRhythmLevels({bassDrum: 5, snare: 6, tom: 6, cymbal: 8, hiHat: 8});\nopll.setVoice(0, {instrument: 8, attenuation: 7, sustain: false});\n\nliveLoop('sms-opll-rhythm', async () => {\n  for (let step = 0; step < 8; step++) {\n    if (step % 2 === 0) opll.noteOn(0, step < 4 ? 'C3' : 'G2');\n    const drum = step % 4 === 0 ? 'bassDrum' : step % 4 === 2 ? 'snare' : 'hiHat';\n    opll.setRhythm({[drum]: true});\n    await beat(0.1);\n    opll.setRhythm({[drum]: false});\n    opll.keyOff(0);\n    await beat(0.4);\n  }\n});\n\n// Rhythm uses CH6..8 instrument/volume nibbles; selecting melody afterward\n// requires assigning their instruments again. Keyboard lists the five drums.\n"
  },
  {
    "path": "/examples/master-system/sms-opll-user-patch.js",
    "name": "sms-opll-user-patch",
    "data": "// Master System: one global User patch shared by every instrument-0 channel.\nsetBpm(120);\nopll.setUserPatch(OPLL_USER_PRESETS.bell);\nopll.setVoice(0, {instrument: 0, attenuation: 5, sustain: false});\nopll.setVoice(1, {instrument: 0, attenuation: 7, sustain: false});\nopll.setVoice(2, {instrument: 4, attenuation: 7, sustain: false}); // ROM Flute is unaffected.\n\nliveLoop('sms-opll-user-chord', async () => {\n  for (const notes of [['C4', 'E4', 'G4'], ['A3', 'C4', 'E4'], ['F3', 'A3', 'C4'], ['G3', 'B3', 'D4']]) {\n    for (let channel = 0; channel < notes.length; channel++) opll.noteOn(channel, notes[channel]);\n    await tween({beats: 1}, progress => opll.setUserOperator(0, {\n      tl: Math.round(36 - 14 * progress), // Modulator level changes CH0 and CH1 together.\n    }));\n    for (const channel of [0, 1, 2]) opll.keyOff(channel);\n    await beat(0.5);\n  }\n});\n\n// Carrier level is set per channel with setAttenuation(channel, 0..15).\n// Editing the User patch does not alter ROM instrument 4 on CH2.\n"
  },
  {
    "path": "/examples/msx/msx-ay-envelope.js",
    "name": "msx-ay-envelope",
    "data": "// MSX AY-3-8910: both voices use the same hardware envelope.\nsetBpm(120);\nay.setVoice(0, {tone: true, noise: false, volume: 9, envelope: true});\nay.setVoice(1, {tone: true, noise: false, volume: 7, envelope: true});\n\nliveLoop('msx-ay-envelope', async () => {\n  for (const [shape, period, notes] of [[8, 1800, ['C4', 'E4']], [10, 1200, ['G3', 'D4']], [12, 2200, ['A3', 'C4']], [14, 1500, ['G3', 'B3']]]) {\n    // Period is a 16-bit hardware value. An explicit Shape write restarts it\n    // globally, once per chord; noteOn itself does not reset the shared envelope.\n    ay.setEnvelope({period, shape});\n    ay.noteOn(0, notes[0]);\n    ay.noteOn(1, notes[1]);\n    await beat(2);\n    ay.keyOff(0);\n    ay.keyOff(1);\n    await beat(0.5);\n  }\n});\n"
  },
  {
    "path": "/examples/msx/msx-ay-tone-noise.js",
    "name": "msx-ay-tone-noise",
    "data": "// MSX AY-3-8910: three voices mix their own tone with one shared noise source.\nsetBpm(120);\nay.setVoice(0, {tone: true, noise: false, volume: 9, envelope: false});\nay.setVoice(1, {tone: false, noise: true, volume: 5, envelope: false});\nay.setVoice(2, {tone: true, noise: true, volume: 4, envelope: false});\n\nliveLoop('msx-ay-tone-noise', async () => {\n  for (const [note, period] of [['C4', 8], ['E4', 16], ['G4', 24], ['C5', 16]]) {\n    ay.setNoisePeriod(period); // Changes the noise on CH1 and CH2 together.\n    ay.noteOn(0, note);\n    ay.keyOn(1); // A noise-only voice keeps its configured noise period.\n    ay.noteOn(2, 'C3');\n    await beat(0.15);\n    ay.keyOff(1);\n    await beat(0.25);\n    ay.keyOff(0);\n    ay.keyOff(2);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/msx/msx-fm-sections.js",
    "name": "msx-fm-sections",
    "data": "// MSX: YM2413 OPLL and Y8950 OPL are separate FM chips.\nsetBpm(120);\nopll.setUserPatch(OPLL_USER_PRESETS.bell); // One shared User patch, not one per CH.\nopll.setVoice(0, {instrument: 0, attenuation: 6, sustain: false});\nopll.setVoice(1, {instrument: 4, attenuation: 7, sustain: false}); // ROM Flute.\nopl.setPreset(0, OPL_PRESETS.organ);\nopl.setOperator(0, 0, {tl: 30});\nopl.setOperator(0, 1, {tl: 26});\n\nliveLoop('msx-two-fm-chips', async () => {\n  for (const notes of [['C4', 'E4', 'G3'], ['A3', 'C4', 'E3'], ['F3', 'A3', 'C3'], ['G3', 'B3', 'D3']]) {\n    opll.noteOn(0, notes[0]);\n    opll.noteOn(1, notes[1]);\n    opl.noteOn(0, notes[2]);\n    await beat(0.8);\n    opll.keyOff(0);\n    opll.keyOff(1);\n    opl.keyOff(0);\n    await beat(0.2);\n  }\n});\n\n// Both FM chips have nine melodic channels (0..8); rhythm changes ownership.\n// The OPLL User patch affects instrument-0 channels only; ROM Flute stays fixed.\n"
  },
  {
    "path": "/examples/msx/msx-music-duet.js",
    "name": "msx-music-duet",
    "data": "// MSX / MSX Audio: one shared OPLL user patch over a PSG bass line.\nsetBpm(120);\nopll.setUserPatch(OPLL_USER_PRESETS.bell);\nopll.setVoice(0, {instrument: 0, attenuation: 5, sustain: false});\nopll.setVoice(1, {instrument: 0, attenuation: 8, sustain: false});\nay.setVoice(0, {tone: true, noise: false, volume: 7, envelope: false});\n\nliveLoop('msx-music-duet', async () => {\n  for (const [bass, low, high] of [\n    ['C3', 'E4', 'G4'], ['A2', 'C4', 'E4'],\n    ['F2', 'A3', 'C4'], ['G2', 'B3', 'D4'],\n  ]) {\n    ay.noteOn(0, bass);\n    opll.noteOn(0, low);\n    opll.noteOn(1, high);\n    await beat(0.8);\n    ay.keyOff(0);\n    opll.keyOff(0);\n    opll.keyOff(1);\n    await beat(0.2);\n  }\n});\n\n// Both instrument-0 voices use the same eight user-patch registers.\n// Built-in instruments 1..15 are independent of that shared custom patch.\n"
  },
  {
    "path": "/examples/gameboy/gameboy-mode-noise.js",
    "name": "gameboy-mode-noise",
    "data": "// Select Mode: Game Boy. Shape percussion with the built-in noise channel.\nsetBpm(120);\n\nliveLoop('noise-drums', async () => {\n  for (let step = 0; step < 8; step++) {\n    gameboy.noise.setVoice({\n      volume: step % 2 ? 7 : 10,\n      envelope: {direction: 'down', period: 1},\n      divisor: step % 2 ? 1 : 4,\n      shift: step % 2 ? 2 : 5,\n      width: 15,\n    });\n    gameboy.noise.keyOn();\n    await beat(0.2);\n    gameboy.noise.keyOff();\n    await beat(0.3);\n  }\n});\n"
  },
  {
    "path": "/examples/gameboy/gameboy-mode-pulse.js",
    "name": "gameboy-mode-pulse",
    "data": "// Select Mode: Game Boy. Main / Worker use the same built-in APU.\n// pulse: channels 0/1, wave: channel 2, noise: channel 3.\nsetBpm(120);\ngameboy.pulse.setVoice(0, {\n  duty: 0.25, volume: 9, envelope: {direction: 'down', period: 0},\n});\n\nliveLoop('melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4']) {\n    gameboy.pulse.noteOn(0, note);\n    await beat(0.4);\n    gameboy.pulse.keyOff(0);\n    await beat(0.1);\n  }\n});\n\n// Other voices: gameboy.wave.noteOn('C3'), gameboy.noise.keyOn().\n// Configure them through gameboy.wave / gameboy.noise before starting.\n// Global play() is an FM shortcut in OPN modes; Game Boy uses its own API.\n"
  },
  {
    "path": "/examples/gameboy/gameboy-mode-wave.js",
    "name": "gameboy-mode-wave",
    "data": "// Select Mode: Game Boy. Use the built-in 32-sample, four-bit wave channel.\nsetBpm(120);\ngameboy.wave.stopAndSetWaveform(\n  Array.from({length: 32}, (_, i) => i < 16 ? i : 31 - i),\n);\ngameboy.wave.setLevel(0.5);\n\nliveLoop('wave-bass', async () => {\n  for (const note of ['C3', 'C3', 'G2', 'G2', 'A2', 'A2', 'F2', 'G2']) {\n    gameboy.wave.noteOn(note);\n    await beat(0.4);\n    gameboy.wave.keyOff();\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/gameboy/gameboy-sampler.js",
    "name": "gameboy-sampler",
    "data": "// Select one cycle in Sample Editor; Game Boy stores 32 four-bit wave samples.\n// Sample Editor で1周期を選択して、Run → Keyboard で演奏します。wave RAM は同時1音です。\nconst audio = await inputAudio({asset: '/samples/sampler.sample.json', edit: false});\nif (audio) {\n  keyboard.bind('sampler', await createSampleInstrument(audio));\n  log('Wave RAM ready. Open Keyboard to play. Edit /samples/sampler.sample.json to redraw the wave.');\n}\n"
  },
  {
    "path": "/examples/gameboy/gameboy-saw-noise.js",
    "name": "gameboy-saw-noise",
    "data": "// Game Boyノイズ：15-bitと7-bitの違い、分周とシフトを試します。\n// noiseには音名指定がありません。設定は即時書き込み、keyOn()で発音・エンベロープを開始します。\nconst gb = await createSoundChip('gameboy');\ntry {\n  gb.initialize();\n  for (const width of /** @type {const} */ ([15, 7])) {\n    for (const shift of [2, 3, 4, 5]) {\n      gb.noise.setVoice({\n        volume: 10,\n        envelope: {direction: 'down', period: 1},\n        divisor: 3, shift, width,\n      });\n      gb.noise.keyOn();\n      await sleep(0.2);\n      gb.noise.keyOff();\n      await sleep(0.1);\n    }\n  }\n} finally {\n  gb.dispose();\n}\n"
  },
  {
    "path": "/examples/gameboy/gameboy-saw-pulse.js",
    "name": "gameboy-saw-pulse",
    "data": "// Game Boy pulse: 高水準APIでデューティ比と左右出力を比較。\n// 2つの矩形波CHを左右に振り分け、4種類のデューティ比を比較します。\nconst gb = await createSoundChip('gameboy');\ntry {\n  gb.initialize();\n  gb.setPan(0, true, false);\n  gb.setPan(1, false, true);\n  for (const duty of /** @type {const} */ ([0.125, 0.25, 0.5, 0.75])) {\n    for (const ch of /** @type {const} */ ([0, 1])) {\n      gb.pulse.setVoice(ch, {\n        duty, volume: 10, envelope: {direction: 'down', period: 2},\n      });\n    }\n    for (const note of ['C4', 'E4', 'G4', 'C5']) {\n      gb.pulse.setNote(0, note);\n      gb.pulse.setNote(1, 'C4');\n      gb.pulse.keyOn(0);\n      gb.pulse.keyOn(1);\n      await sleep(0.2);\n      gb.pulse.keyOff(0);\n      gb.pulse.keyOff(1);\n      await sleep(0.05);\n    }\n  }\n} finally {\n  gb.dispose();\n}\n"
  },
  {
    "path": "/examples/gameboy/gameboy-saw-wave.js",
    "name": "gameboy-saw-wave",
    "data": "// Game Boyの波形メモリー：32点、各0〜15。三角波とノコギリ波を比較します。\nconst gb = await createSoundChip('gameboy');\ntry {\n  gb.initialize();\n  const triangle = Array.from({length: 32}, (_, i) => i < 16 ? i : 31 - i);\n  const sawtooth = Array.from({length: 32}, (_, i) => Math.floor(i / 2));\n  for (const waveform of [triangle, sawtooth]) {\n    // 転送時にwaveは停止します。再生開始はkeyOn()で明示します。\n    gb.wave.setWaveform(waveform);\n    gb.wave.setLevel(0.5);\n    for (const note of ['C3', 'E3', 'G3', 'C4']) {\n      gb.wave.setNote(note);\n      gb.wave.keyOn();\n      await sleep(0.25);\n      gb.wave.keyOff();\n      await sleep(0.05);\n    }\n  }\n} finally {\n  gb.dispose();\n}\n"
  },
  {
    "path": "/examples/gameboy/gameboy-synth.js",
    "name": "gameboy-synth",
    "data": "// Game Boy: change duty and noise while notes are held, without retriggering.\nconst gb = await createSoundChip('gameboy');\ntry {\n  gb.initialize();\n  gb.pulse.setDuty(0, 0.25);\n  // Initial volume and hardware envelope; keyOn explicitly starts the envelope.\n  gb.pulse.setEnvelope(0, {volume: 10, direction: 'down', period: 0});\n  gb.pulse.setNote(0, 'C4');\n  gb.pulse.keyOn(0);\n  for (const duty of /** @type {const} */ ([0.125, 0.25, 0.5, 0.75])) {\n    gb.pulse.setDuty(0, duty); // Live NR11 update, no keyOn.\n    await sleep(0.2);\n  }\n  gb.pulse.keyOff(0);\n  gb.wave.stopAndSetWaveform(Array.from({length: 32}, (_, i) => i < 16 ? i : 31 - i));\n  gb.wave.setNote('C3');\n  gb.wave.keyOn(); // Wave upload stopped the DAC; restart explicitly.\n  await sleep(0.25);\n  gb.wave.keyOff();\n  gb.noise.setEnvelope({volume: 8, direction: 'down', period: 0});\n  gb.noise.setParameters({divisor: 3, shift: 4, width: 15});\n  gb.noise.keyOn();\n  await sleep(0.2);\n  gb.noise.setParameters({width: 7, shift: 3}); // Live NR43 update.\n  await sleep(0.2);\n  gb.noise.keyOff();\n} finally {\n  gb.dispose();\n}\n"
  },
  {
    "path": "/examples/nes/nes-apu-tones.js",
    "name": "nes-apu-tones",
    "data": "// NES APU: two pulse voices, triangle bass, and noise percussion.\nconst nes = await useSoundChip('nes');\ntry {\n  await mixer.set(nes.id, {volume: 0.6});\n  nes.pulse.setVoice(0, {duty: 0.25, volume: 8});\n  nes.pulse.setVoice(1, {duty: 0.5, volume: 5});\n  nes.noise.setVoice({volume: 4, period: 6});\n  const melody = ['C4', 'E4', 'G4', 'B4', 'A4', 'G4', 'E4', 'D4'];\n  for (const note of melody) {\n    nes.pulse.noteOn(0, note);\n    nes.pulse.noteOn(1, 'G3');\n    nes.triangle.noteOn('C3'); // Triangle has a fixed hardware volume.\n    nes.noise.noteOn();\n    await sleep(0.04);\n    nes.noise.noteOff();\n    await sleep(0.16);\n    nes.pulse.noteOff(0); nes.pulse.noteOff(1); nes.triangle.noteOff();\n    await sleep(0.04);\n  }\n} finally { nes.dispose(); }\n"
  },
  {
    "path": "/examples/nes/nes-dmc-sample.js",
    "name": "nes-dmc-sample",
    "data": "// DMC plays 1-bit DPCM bytes, not ordinary PCM. No cartridge or ROM needed.\nconst nes = await createSoundChip('nes');\ntry {\n  await mixer.set(nes.id, {volume: 0.6});\n  // Alternating runs of increasing/decreasing DAC steps form a repeating wave.\n  const dpcm = Uint8Array.from({length: 257}, (_, i) => i % 8 < 4 ? 0xff : 0x00);\n  await nes.dmc.loadSample(dpcm); // Wait until sample RAM is ready in the Worklet.\n  for (const rate of [8, 12, 15]) {\n    nes.dmc.play({rate, loop: true, level: 64});\n    await sleep(0.5);\n    nes.dmc.stop();\n    await sleep(0.1);\n  }\n} finally { nes.dispose(); }\n"
  },
  {
    "path": "/examples/nes/nes-fds-wave.js",
    "name": "nes-fds-wave",
    "data": "// FDS: a custom 64-entry waveform, then the same melody with modulation.\nconst nes = await createSoundChip('nes', {fds: true});\ntry {\n  await mixer.set(nes.id, {volume: 0.5});\n  nes.fds.setWave(Array.from({length: 64}, (_, i) =>\n    Math.round(31.5 + 23 * Math.sin(i * Math.PI / 32) + 8 * Math.sin(i * Math.PI / 16))));\n  nes.fds.setVolume(24);\n  for (const enabled of [false, true]) {\n    nes.fds.setModulation({\n      table: Array.from({length: 32}, (_, i) => i < 16 ? 1 : 7),\n      rate: 80, depth: 10, bias: 0, enabled,\n    });\n    for (const note of ['C4', 'E4', 'G4', 'C5']) {\n      nes.fds.noteOn(note);\n      await sleep(0.3);\n      nes.fds.noteOff();\n      await sleep(0.05);\n    }\n  }\n} finally { nes.dispose(); }\n"
  },
  {
    "path": "/examples/nes/nes-mode-fds.js",
    "name": "nes-mode-fds",
    "data": "// Select Mode: NES + FDS. Original 64-entry waveform, no disk image needed.\nsetBpm(110);\nnes.fds.setWave(Array.from({length:64}, (_, index) =>\n  Math.round(31.5 + 23 * Math.sin(index * Math.PI / 32) + 8 * Math.sin(index * Math.PI / 16))));\nnes.fds.setVolume(24);\nnes.fds.setModulation({\n  table:Array.from({length:32}, (_, index) => index < 16 ? 1 : 7),\n  rate:80, depth:8, bias:0, enabled:true,\n});\n\nliveLoop('fds-melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'C5', 'B4', 'G4', 'E4', 'D4']) {\n    nes.fds.noteOn(note);\n    await beat(0.4);\n    nes.fds.noteOff();\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/nes/nes-mode-pulse.js",
    "name": "nes-mode-pulse",
    "data": "// Select Mode: NES + FDS. Built-in pulse voices use physical channels 0/1.\nsetBpm(120);\nnes.pulse.setVoice(0, {duty:0.25, volume:8});\n\nliveLoop('nes-melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4']) {\n    nes.pulse.noteOn(0, note);\n    await beat(0.4);\n    nes.pulse.noteOff(0);\n    await beat(0.1);\n  }\n});\n\n// Other voices: nes.triangle.noteOn('C3'), nes.noise.noteOn(), nes.fds.noteOn('C4').\n"
  },
  {
    "path": "/examples/nes/nes-mode-rhythm.js",
    "name": "nes-mode-rhythm",
    "data": "// Select Mode: NES + FDS. Triangle bass and short/long noise percussion.\nsetBpm(120);\n\nliveLoop('nes-rhythm', async () => {\n  const bassLine = ['C3', 'C3', 'G2', 'C3', 'F2', 'F2', 'G2', 'G2'];\n  for (let step = 0; step < bassLine.length; step++) {\n    nes.triangle.noteOn(bassLine[step]);\n    nes.noise.setVoice({volume:step % 2 ? 5 : 8, period:step % 2 ? 5 : 10, shortMode:false});\n    nes.noise.noteOn();\n    await beat(0.12);\n    nes.noise.noteOff();\n    await beat(0.28);\n    nes.triangle.noteOff();\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/nes/nes-pulse-frequency.js",
    "name": "nes-pulse-frequency",
    "data": "// Hz and note names are separate APIs: noteOn(channel, note) sets a musical note.\n// setFrequency(channel, hz) + keyOn(channel) uses the configured frequency.\nconst nes = await useSoundChip('nes');\ntry {\n  nes.pulse.setVoice(0, {duty: 0.5, volume: 8});\n  nes.pulse.setFrequency(0, 440);\n  nes.pulse.keyOn(0);\n  await sleep(0.3);\n  // Change Hz while sounding, without choosing a new note name.\n  nes.pulse.setFrequency(0, 660);\n  await sleep(0.3);\n  nes.pulse.keyOff(0);\n  await sleep(0.15);\n  // Restart the same 660 Hz pitch.\n  nes.pulse.keyOn(0);\n  await sleep(0.3);\n  nes.pulse.keyOff(0);\n} finally {\n  nes.dispose();\n}\n"
  },
  {
    "path": "/examples/pc98/pc98-opn-melody.js",
    "name": "pc98-opn-melody",
    "data": "// Select Mode: PC-98 (YM2203 / OPN).\n// FM and SSG share one mono YM2203, sent equally to left and right.\nsetBpm(120);\nfm.setPreset(CH1, FM_PRESETS['one-op-basic']);\nssg.setMixer(0, {tone: true, noise: false});\nssg.setVolume(0, 8);\n\nliveLoop('opn-melody', async () => {\n  const lead = ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4'];\n  const bass = ['C3', 'C3', 'G2', 'G2', 'A2', 'A2', 'G2', 'G2'];\n  for (let step = 0; step < lead.length; step++) {\n    ssg.noteOn(0, bass[step]);\n    await play(lead[step], {channel: CH1, beats: 0.4});\n    ssg.keyOff(0);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/pc98/pc98-opn-ssg.js",
    "name": "pc98-opn-ssg",
    "data": "// Select Mode: PC-98 (YM2203 / OPN). Works in Main and Worker.\n// fm and the three SSG channels share the default YM2203.\nsetBpm(120);\nfm.setPreset(CH1, FM_PRESETS['one-op-basic']);\nawait play('C4', {channel: CH1, beats: 1});\n\n// Tone: Hz uses the YM2203 SSG clock (master / 2).\nssg.tone(0, {frequency: 440, volume: 10});\nawait beat(1);\nssg.keyOff(0);\n\n// Noise: period is shared across the noise-enabled SSG channels.\nssg.noise(1, {period: 16, volume: 8});\nawait beat(1);\nssg.keyOff(1);\n\n// Envelope: its generator is shared across envelope-enabled channels.\nssg.setEnvelope({period: 2000, shape: 9});\nssg.tone(2, {frequency: 880, envelope: true});\nawait beat(1);\nssg.keyOff(2);\n"
  },
  {
    "path": "/examples/pc98/pc98-opna-groove.js",
    "name": "pc98-opna-groove",
    "data": "// Select Mode: PC-98 (YM2608 / OPNA).\n// Built-in FM, SSG and rhythm; bundled synthetic drums need no ROM upload.\nsetBpm(120);\nfm.setPreset(CH1, FM_PRESETS['one-op-basic']);\nssg.setMixer(0, {tone: true, noise: false});\nssg.setVolume(0, 8);\nrhythm.setVolume(48);\nfor (const voice of ['bassDrum', 'snare', 'hiHat']) {\n  rhythm.setVoice(voice, {volume: 24, left: true, right: true});\n}\n\nliveLoop('opna-groove', async () => {\n  const lead = ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4'];\n  for (let step = 0; step < lead.length; step++) {\n    rhythm.keyOn([step % 2 ? 'snare' : 'bassDrum', 'hiHat']);\n    ssg.noteOn(0, step < 4 ? 'C3' : 'G2');\n    await play(lead[step], {channel: CH1, beats: 0.4});\n    ssg.keyOff(0);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/pc98/pc98-opna-sections.js",
    "name": "pc98-opna-sections",
    "data": "// Select Mode: PC-98 (YM2608 / OPNA). Works in Main and Worker.\n// fm, ssg, rhythm and adpcm share the default YM2608; no useSoundChip needed.\nsetBpm(120);\n\n// FM: one operator sine.\nfm.setPreset(0, FM_PRESETS['one-op-basic']);\nawait play('C4', {channel: CH1, beats: 1});\n\n// SSG: tone, then shared noise on channel 0.\nssg.tone(0, {frequency: 440, volume: 10});\nawait beat(1);\nssg.noise(0, {period: 16, volume: 8});\nawait beat(1);\nssg.keyOff(0);\n\n// Rhythm: the bundled synthetic sounds are ready to use.\nrhythm.setVolume(48);\nfor (const voice of ['bassDrum', 'snare', 'hiHat']) {\n  rhythm.setVoice(voice, {volume: 24, left: true, right: true});\n}\nfor (let step = 0; step < 8; step++) {\n  rhythm.keyOn([step % 2 ? 'snare' : 'bassDrum', 'hiHat']);\n  await beat(0.5);\n}\n\n// ADPCM-B: encode and upload an original PCM tone before starting playback.\nconst sampleRate = 8000;\nconst wave = new Float32Array(4000);\nfor (let i = 0; i < wave.length; i++) {\n  const fade = Math.min(1, i / 80, (wave.length - 1 - i) / 80);\n  wave[i] = 0.6 * fade * Math.sin(2 * Math.PI * 330 * i / sampleRate);\n}\nconst adpcmSample = await adpcm.loadSample({channels: [wave], sampleRate});\nadpcm.setVolume(180);\nadpcm.setPan(true, true);\nadpcm.keyOn();\nawait sleep(adpcmSample.duration + 0.05);\nadpcm.keyOff();\n"
  },
  {
    "path": "/examples/pc98/pc98-sampler.js",
    "name": "pc98-sampler",
    "data": "// Edit /samples/sampler.sample.json in Sample Editor, then Run → open Keyboard.\n// YM2608 ADPCM-B: one PCM voice with variable pitch and whole-sample repeat.\nconst audio = await inputAudio({asset: '/samples/sampler.sample.json', edit: false});\nif (audio) {\n  keyboard.bind('sampler', await createSampleInstrument(audio));\n  log('ADPCM-B sampler ready. Open Keyboard to play. Edit /samples/sampler.sample.json to change the sound.');\n}\n"
  },
  {
    "path": "/examples/pc98/ym2608-adpcm-load-sample.js",
    "name": "ym2608-adpcm-load-sample",
    "data": "// Independent YM2608: works with any chip selected in the Playground UI.\n// loadSample accepts decoded PCM here, and converts it to Yamaha ADPCM-B.\nconst ym2608 = await useSoundChip('ym2608');\ntry {\n  const sampleRate = 8000;\n  const frames = 4000;\n  const wave = new Float32Array(frames);\n  for (let i = 0; i < frames; i++) {\n    // Original 440 Hz tone with 10 ms fades. No external file or ROM needed.\n    const fade = Math.min(1, i / 80, (frames - 1 - i) / 80);\n    wave[i] = 0.6 * fade * Math.sin(i * 2 * Math.PI * 440 / sampleRate);\n  }\n\n  // Mix PCM to mono, encode ADPCM-B, upload it and set the sample range/rate.\n  // address must be 32-byte aligned. Loading does not start playback.\n  const sample = await ym2608.adpcm.loadSample(\n    {channels: [wave], sampleRate},\n    {address: 0},\n  );\n  ym2608.adpcm.setVolume(180);\n  ym2608.adpcm.setPan(true, true);\n  ym2608.adpcm.keyOn();\n  await sleep(sample.duration + 0.05);\n  ym2608.adpcm.keyOff();\n\n  // Reuse the same memory at 1.5x speed: higher pitch, shorter duration.\n  ym2608.adpcm.setPlaybackRate(sample.sampleRate * 1.5);\n  ym2608.adpcm.keyOn();\n  await sleep(sample.duration / 1.5 + 0.05);\n  ym2608.adpcm.keyOff();\n\n  // For a PCM/Float WAV imported into FILES, the loading step can instead be:\n  // const wav = await file('./samples/voice.wav', {type: 'arrayBuffer'});\n  // const sample = await ym2608.adpcm.loadSample(wav, {address: 0});\n  // loadMemory() is for already-encoded ADPCM-B bytes, not WAV/Float32 PCM.\n} finally {\n  ym2608.dispose();\n}\n"
  },
  {
    "path": "/examples/pc98/ym2608-chip.js",
    "name": "ym2608-chip",
    "data": "// Independent YM2608: works alongside the chip selected in the Playground UI.\nconst ym2608 = await createSoundChip('ym2608');\nym2608.reset();\nym2608.ssg.tone(0, {frequency: 440, volume: 10});\nawait sleep(0.4);\nym2608.ssg.off(0);\nym2608.rhythm.setVolume(48);\nfor (let voice = 0; voice < 6; voice++) {\n  ym2608.rhythm.setVoice(voice, {volume: 24, left: true, right: true});\n  ym2608.rhythm.keyOn(voice);\n  await sleep(0.75);\n}\n// ADPCM-B takes encoded bytes, not WAV. This synthetic fixture needs no ROM.\nawait ym2608.adpcm.loadMemory(new Uint8Array(256).fill(0x17));\nym2608.adpcm.setSample({start: 0, end: 256});\nym2608.adpcm.setVolume(160);\nym2608.adpcm.setPan(true, true);\nym2608.adpcm.setPlaybackRate(8000);\nym2608.adpcm.keyOn();\nawait sleep(0.3);\nym2608.dispose();\n"
  },
  {
    "path": "/examples/pc98/ym2608-rhythm.js",
    "name": "ym2608-rhythm",
    "data": "// Independent YM2608; no need to change the Playground chip selector.\n// Uses the bundled BSD-3-Clause Tetorica synthetic rhythm sounds.\n// These sounds differ from Yamaha's original ROM.\nconst ym2608 = await createSoundChip('ym2608');\ntry {\n  ym2608.reset();\n  const rhythm = ym2608.rhythm;\n  rhythm.setVolume(48);\n  for (let voice = 0; voice < 6; voice++) {\n    rhythm.setVoice(voice, {volume: 24, left: true, right: true});\n    rhythm.keyOn(voice);\n    await sleep(0.75);\n  }\n  for (let step = 0; step < 8; step++) {\n    rhythm.keyOn([step % 2 ? 'snare' : 'bassDrum', 'hiHat']);\n    await sleep(0.25);\n  }\n} finally {\n  ym2608.dispose();\n}\n"
  },
  {
    "path": "/examples/neogeo/neogeo-b-six-channel.js",
    "name": "neogeo-b-six-channel",
    "data": "// Select Mode: Neo Geo (YM2610B). This uses all six FM channels.\nsetBpm(120);\nconst channels = /** @type {const} */ ([CH1, CH2, CH3, CH4, CH5, CH6]);\nfor (const channel of channels) {\n  fm.setPreset(channel, FM_PRESETS['one-op-basic']);\n}\n\nliveLoop('six-channel-chords', async () => {\n  for (const chord of [\n    ['C3', 'G3', 'C4', 'E4', 'G4', 'B4'],\n    ['A2', 'E3', 'A3', 'C4', 'E4', 'G4'],\n    ['F2', 'C3', 'F3', 'A3', 'C4', 'E4'],\n    ['G2', 'D3', 'G3', 'B3', 'D4', 'F4'],\n  ]) {\n    for (let i = 0; i < channels.length; i++) {\n      fm.noteOn(channels[i], chord[i]);\n    }\n    await beat(0.75);\n    for (const channel of channels) fm.keyOff(channel);\n    await beat(0.25);\n  }\n});\n"
  },
  {
    "path": "/examples/neogeo/neogeo-opnb-duet.js",
    "name": "neogeo-opnb-duet",
    "data": "// Select Mode: Neo Geo (YM2610) or Neo Geo (YM2610B).\n// FM and SSG use the standard chip; ADPCM sections are available separately.\nsetBpm(120);\nfm.setPreset(CH1, FM_PRESETS['one-op-basic']);\nssg.setMixer(0, {tone: true, noise: false});\nssg.setVolume(0, 8);\n\nliveLoop('opnb-duet', async () => {\n  const lead = ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4'];\n  for (let step = 0; step < lead.length; step++) {\n    ssg.noteOn(0, step < 4 ? 'C3' : 'G2');\n    await play(lead[step], {channel: CH1, beats: 0.4});\n    ssg.keyOff(0);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/neogeo/neogeo-opnb-sections.js",
    "name": "neogeo-opnb-sections",
    "data": "// Select Mode: Neo Geo (FM 4ch) or Neo Geo (YM2610B, FM 6ch).\n// Main / Worker: all sections share the default chip. No extra chip is needed.\nsetBpm(120);\nfm.setPreset(CH1, FM_PRESETS['one-op-basic']);\nawait play('C4', {channel: CH1, beats: 1});\n// In YM2610B mode, CH5 and CH6 are available as well.\n\nssg.tone(0, {frequency: 440, volume: 10});\nawait beat(1);\nssg.noise(0, {period: 16, volume: 8});\nawait beat(1);\nssg.keyOff(0);\n\n// Original test patterns of encoded ADPCM nibbles; no external ROM or WAV.\n// A and B have separate memories and use 256-byte aligned sample ranges.\nawait adpcmA.loadMemory(new Uint8Array(256).fill(0x17));\nadpcmA.setVolume(48);\nfor (let voice = 0; voice < 6; voice++) {\n  adpcmA.setSample(voice, {start: 0, end: 256});\n  adpcmA.setVoice(voice, {volume: 24, left: true, right: true});\n  adpcmA.keyOn(voice);\n  await beat(0.5);\n}\nadpcmA.keyOff([0, 1, 2, 3, 4, 5]);\n\n// ADPCM-B: adjustable rate and whole-sample repeat. adpcm === adpcmB.\nawait adpcmB.loadMemory(new Uint8Array(256).fill(0x17));\nadpcmB.setSample({start: 0, end: 256});\nadpcmB.setPlaybackRate(8000);\nadpcmB.setVolume(160);\nadpcmB.setPan(true, true);\nadpcmB.keyOn({repeat: true});\nawait beat(2);\nadpcmB.keyOff();\n"
  },
  {
    "path": "/examples/neogeo/neogeo-sampler.js",
    "name": "neogeo-sampler",
    "data": "// Edit /samples/sampler.sample.json in Sample Editor, then Run → open Keyboard.\n// YM2610/B ADPCM-B: one pitched PCM voice. Memory ranges use 256-byte units.\nconst audio = await inputAudio({asset: '/samples/sampler.sample.json', edit: false});\nif (audio) {\n  keyboard.bind('sampler', await createSampleInstrument(audio));\n  log('ADPCM-B sampler ready. Open Keyboard to play. Edit /samples/sampler.sample.json to change the sound.');\n}\n"
  },
  {
    "path": "/examples/x68000/x68000-mode-adpcm.js",
    "name": "x68000-mode-adpcm",
    "data": "// Select Mode: X68000. Original PCM is encoded to the built-in OKIM6258's ADPCM.\nsetBpm(120);\nawait livePrepare('x68000-mode-original-kick', async () => {\n  const pcmRate = 15625; // 8 MHz / 512, one of the chip's three hardware rates.\n  const drumPcm = Float32Array.from({length:3125}, (_, index) => {\n    const seconds = index / pcmRate;\n    const phase = 2 * Math.PI * (65 * seconds + 3 * (1 - Math.exp(-seconds * 45)));\n    return 0.6 * Math.sin(phase) * Math.exp(-seconds * 22);\n  });\n  return adpcm.loadSample({channels:[drumPcm], sampleRate:pcmRate}, {sampleRate:pcmRate});\n});\nadpcm.setPan(true, true);\n\nliveLoop('x68000-adpcm-drums', async () => {\n  for (let step = 0; step < 8; step++) {\n    adpcm.play(); // The OKIM6258 has one sample stream, with no per-note pitch register.\n    await beat(0.4);\n    adpcm.stop();\n    await beat(step === 7 ? 0.6 : 0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/x68000/x68000-mode-opm.js",
    "name": "x68000-mode-opm",
    "data": "// Select Mode: X68000. Built-in YM2151, channels 0..7; operators M1/C1/M2/C2.\nsetBpm(120);\nopm.setAlgo(0, 7);\nopm.setPan(0, true, true);\nopm.setOperator(0, 3, {mul:1, tl:32, ar:31, d1r:0, d2r:0, d1l:0, rr:15});\n\nliveLoop('x68000-opm-melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4']) {\n    opm.setNote(0, note);\n    opm.keyOn(0, 8); // Only C2, one of algorithm 7's four parallel carriers.\n    await beat(0.4);\n    opm.keyOff(0);\n    await beat(0.1);\n  }\n});\n\n// The built-in adpcm device is the X68000's mono OKIM6258.\n"
  },
  {
    "path": "/examples/x68000/ym2151-tone.js",
    "name": "ym2151-tone",
    "data": "// Independent OPM; numeric channels 0..7. Operator order: M1, C1, M2, C2.\nconst opm = await useSoundChip('ym2151');\ntry {\n  opm.reset();\n  opm.setAlgo(0, 7); // Four parallel carriers; enable only C2 below.\n  opm.setPan(0, true, true);\n  opm.setOperator(0, 3, {mul: 1, tl: 32, ar: 31, d1r: 0, d2r: 0, d1l: 0, rr: 15});\n  for (const note of ['C4', 'E4', 'G4', 'A4']) {\n    opm.setNote(0, note);\n    opm.keyOn(0, 8); // Only C2.\n    await sleep(0.2);\n    opm.keyOff(0);\n    await sleep(0.05);\n  }\n} finally { opm.dispose(); }\n"
  },
  {
    "path": "/examples/dx7/dx7-init-sine.js",
    "name": "dx7-init-sine",
    "data": "// Independent MSFA DX7, ready with the self-authored INIT SINE voice.\n// MIDI note numbers 0..127; the DX7 allocates its own 16 voices.\nconst synth = await useSoundChip('dx7');\nsetBpm(110);\nawait mixer.set(synth.id, {volume: 0.5});\n\n// To use your own DX7 SysEx, import a .syx file into FILES first:\n// await synth.loadSysex(await file('/presets/my-bank.syx', {type:'arrayBuffer'}));\n// console.log(synth.voices);\n// synth.selectVoice(0);\n\nliveLoop('dx7-melody', async () => {\n  for (const note of [60, 64, 67, 72, 67, 64]) {\n    synth.noteOn(note, 100);\n    await beat(0.4);\n    synth.noteOff(note);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/dx7/dx7-keyboard.js",
    "name": "dx7-keyboard",
    "data": "// Run, then open Keyboard to play this original DX7 voice.\n// Guitar / Bass / Ukulele input shares this binding. No SysEx file is needed.\nconst synth = await useSoundChip('dx7');\nawait synth.setPreset({\n  name: 'KEYBOARD', algorithm: 0, feedback: 0,\n  operators: {\n    1: {\n      coarse: 1, outputLevel: 85,\n      envelope: {rates: [99, 80, 70, 75], levels: [99, 90, 80, 0]},\n    },\n    2: {\n      coarse: 2, outputLevel: 55,\n      envelope: {rates: [99, 70, 50, 75], levels: [99, 70, 40, 0]},\n    },\n  },\n});\nawait mixer.set(synth.id, {volume: 0.5});\n\n// DX7 noteOff releases every voice at that pitch. Keep the latest press ID\n// for each MIDI note so an older release cannot cut off a newer press.\nconst held = new Map();\nkeyboard.bind('DX7 Keyboard', {\n  noteOn({id, midi, velocity}) {\n    held.set(midi, id);\n    synth.noteOn(midi, velocity);\n  },\n  noteOff({id, midi}) {\n    if (held.get(midi) !== id) return;\n    held.delete(midi);\n    synth.noteOff(midi);\n  },\n  allNotesOff() {\n    held.clear();\n    synth.allNotesOff();\n  },\n});\nlog('DX7 ready. Open Keyboard to play. Stop releases this binding.');\n"
  },
  {
    "path": "/examples/dx7/dx7-live-parameters.js",
    "name": "dx7-live-parameters",
    "data": "// Live DX7 operator editing (tetorica-fm2612 0.2.16 / DX7 core 0.3.0).\n// Level/frequency edits affect this patch's held notes and release tails.\nconst synth = await useSoundChip('dx7');\nawait synth.setPreset({\n  name: 'LIVE FM', algorithm: 0,\n  operators: {\n    1: {outputLevel: 80, envelope: {rates: [99, 99, 99, 75], levels: [99, 99, 99, 0]}},\n    2: {coarse: 2, outputLevel: 20, envelope: {rates: [99, 99, 99, 75], levels: [99, 99, 99, 0]}},\n  },\n});\nawait mixer.set(synth.id, {volume: 0.5});\nsetBpm(100);\n\nliveLoop('dx7-live-parameters', async () => {\n  await synth.setOperators([[1, {outputLevel: 80}], [2, {outputLevel: 20, fine: 0}]]);\n  synth.noteOn(60, 100);\n  // Two beats; follows BPM. Returning the Promise waits for each edit.\n  await tween({beats: 2}, progress => synth.setOperator(2, {\n    outputLevel: Math.round(20 + 60 * progress),\n    fine: Math.round(50 * progress),\n  }));\n  await beat(1);\n  // One real second, independent of BPM. The oscillator and EG are not restarted.\n  await tween(1, progress => synth.setOperator(1, {\n    outputLevel: Math.round(80 * (1 - progress)),\n  }));\n  synth.noteOff(60);\n  await beat(1);\n});\n"
  },
  {
    "path": "/examples/dx7/dx7-object-preset.js",
    "name": "dx7-object-preset",
    "data": "// Build a DX7 voice with objects. No SysEx file is needed.\n// Operators are OP1..6; algorithm 0 is the instrument's algorithm 1.\nconst synth = await useSoundChip('dx7');\nawait synth.setPreset({\n  name: 'JS BELL',\n  algorithm: 0,\n  feedback: 0,\n});\nawait synth.setOperators([\n  [1, {\n    coarse: 1, outputLevel: 90,\n    envelope: {rates: [99, 70, 50, 75], levels: [99, 80, 60, 0]},\n  }],\n  [2, {\n    coarse: 2, outputLevel: 68,\n    envelope: {rates: [99, 75, 50, 80], levels: [99, 70, 0, 0]},\n  }],\n]);\nsetBpm(110);\nawait mixer.set(synth.id, {volume: 0.5});\n\nliveLoop('dx7-object-melody', async () => {\n  // Level edits keep other parameters and also affect this patch's release tails.\n  await synth.setOperator(2, {outputLevel: choose([55, 65, 75])});\n  for (const note of [60, 64, 67, 72]) {\n    synth.noteOn(note, 100);\n    await beat(0.4);\n    synth.noteOff(note);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/snes/snes-brr-melody.js",
    "name": "snes-brr-melody",
    "data": "// CPU-free SNES S-DSP: eight physical voices, numbered 0..7.\n// This original 16-sample looping BRR needs no game files.\nconst snes = await useSoundChip('snes');\nconst tone = await livePrepare('snes-original-brr', async () => {\n  const brr = new Uint8Array([0xc3, 0x13, 0x57, 0x75, 0x31, 0xfd, 0xb9, 0x9b, 0xdf]);\n  // At hardware PITCH=4096, 32,000 / 16 = 2,000 Hz.\n  // BRR contains no tuning information: declare it explicitly.\n  return snes.loadBRR(brr, {baseFrequencyHz: 2000, loopStartSamples: 0});\n});\nsnes.setPreset(0, {\n  sample: tone,\n  adsr1: 0x8f, adsr2: 0xe0, gain: 127,\n  volumeLeft: 90, volumeRight: 90,\n});\nsetBpm(110);\nawait mixer.set(snes.id, {volume: 0.5});\n\nliveLoop('snes-melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'C5', 'G4', 'E4']) {\n    snes.noteOn(0, note);\n    await beat(0.4);\n    snes.noteOff(0);\n    await beat(0.1);\n  }\n});\n\n// For an imported BRR, provide its actual root note and loop position:\n// const sample = await snes.loadBRR(await file('/samples/bass.brr', {type:'arrayBuffer'}),\n//   {rootNote:'C3', loopStartSamples:32});\n// await mixer.set(snes.id, {volume:0.4, pan:-0.25});\n// Raw DSP ADSR/GAIN/volume values are hardware values, not seconds or percentages.\n"
  },
  {
    "path": "/examples/snes/snes-mode-brr.js",
    "name": "snes-mode-brr",
    "data": "// Select Mode: SNES. CPU-free S-DSP; original BRR, no game files needed.\nsetBpm(120);\nconst leadSample = await livePrepare('snes-mode-lead-brr', async () => {\n  const brrBytes = new Uint8Array([0xc3, 0x13, 0x57, 0x75, 0x31, 0xfd, 0xb9, 0x9b, 0xdf]);\n  // One looping block = 16 samples at native 32,000 Hz: base frequency 2,000 Hz.\n  return snes.loadBRR(brrBytes, {baseFrequencyHz:2000, loopStartSamples:0});\n});\nsnes.setPreset(0, {\n  sample:leadSample, adsr1:0x8e, adsr2:0xe0, gain:127, // Short hardware attack avoids an abrupt onset.\n  volumeLeft:80, volumeRight:80,\n});\n\nliveLoop('snes-melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4']) {\n    snes.noteOn(0, note);\n    await beat(0.4);\n    snes.noteOff(0);\n    await beat(0.1);\n  }\n});\n\n// Eight physical voices, numbered 0..7. Assign a BRR sample before setting pitch.\n"
  },
  {
    "path": "/examples/snes/snes-mode-stereo.js",
    "name": "snes-mode-stereo",
    "data": "// Select Mode: SNES. Two tuned BRR voices, independently balanced left/right.\nsetBpm(110);\nconst duetSample = await livePrepare('snes-mode-duet-brr', async () =>\n  snes.loadBRR(new Uint8Array([0xc3, 0x13, 0x57, 0x75, 0x31, 0xfd, 0xb9, 0x9b, 0xdf]),\n    {baseFrequencyHz:2000, loopStartSamples:0}));\nsnes.setPreset(0, {\n  sample:duetSample, adsr1:0x8e, adsr2:0xe0, gain:127,\n  volumeLeft:75, volumeRight:15,\n});\nsnes.setPreset(1, {\n  sample:duetSample, adsr1:0x8e, adsr2:0xe0, gain:127,\n  volumeLeft:15, volumeRight:60,\n});\n\nliveLoop('snes-stereo-duet', async () => {\n  const leadLine = ['C4', 'E4', 'G4', 'C5', 'B4', 'G4', 'E4', 'D4'];\n  const bassLine = ['C3', 'C3', 'C3', 'C3', 'G2', 'G2', 'G2', 'G2'];\n  for (let step = 0; step < leadLine.length; step++) {\n    snes.noteOn(0, leadLine[step]); snes.noteOn(1, bassLine[step]);\n    await beat(0.4);\n    snes.noteOff(0); snes.noteOff(1);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/pc-engine/pce-mode-noise.js",
    "name": "pce-mode-noise",
    "data": "// Select Mode: PC Engine. Physical channels 4 and 5 support noise.\nsetBpm(120);\npce.setVolume(4, 24); pce.setPan(4, 15, 10);\npce.setVolume(5, 20); pce.setPan(5, 10, 15);\npce.setNoise(4, {enabled:true, frequency:18});\npce.setNoise(5, {enabled:true, frequency:28}); // Frequency is a hardware code 0..31.\n\nliveLoop('pce-noise-drums', async () => {\n  for (let step = 0; step < 8; step++) {\n    const channel = step % 2 ? 5 : 4;\n    pce.keyOn(channel);\n    await beat(step % 2 ? 0.12 : 0.2);\n    pce.keyOff(channel);\n    await beat(step % 2 ? 0.38 : 0.3);\n  }\n});\n"
  },
  {
    "path": "/examples/pc-engine/pce-mode-stereo.js",
    "name": "pce-mode-stereo",
    "data": "// Select Mode: PC Engine. Two waveforms with independent stereo balance.\nsetBpm(110);\npce.setWaveform(0, Array.from({length:32}, (_, index) => index < 16 ? 31 : 0));\npce.setWaveform(1, Array.from({length:32}, (_, index) => index));\npce.setVolume(0, 22); pce.setPan(0, 15, 5);\npce.setVolume(1, 22); pce.setPan(1, 5, 15);\n\nliveLoop('pce-stereo-duet', async () => {\n  const leadLine = ['C4', 'E4', 'G4', 'C5', 'B4', 'G4', 'E4', 'D4'];\n  const bassLine = ['C3', 'C3', 'C3', 'C3', 'G2', 'G2', 'G2', 'G2'];\n  for (let step = 0; step < leadLine.length; step++) {\n    pce.noteOn(0, leadLine[step]); pce.noteOn(1, bassLine[step]);\n    await beat(0.4);\n    pce.keyOff(0); pce.keyOff(1);\n    await beat(0.1);\n  }\n});\n"
  },
  {
    "path": "/examples/pc-engine/pce-mode-wave.js",
    "name": "pce-mode-wave",
    "data": "// Select Mode: PC Engine. Six 32-entry, five-bit wavetable voices.\nsetBpm(120);\npce.setWaveform(0, Array.from({length:32}, (_, index) =>\n  Math.round(15.5 + 15.5 * Math.sin(index * Math.PI / 16))));\npce.setVolume(0, 26); // Hardware volume 0..31.\npce.setPan(0, 15, 15); // Independent left/right balances 0..15.\n\nliveLoop('pce-melody', async () => {\n  for (const note of ['C4', 'E4', 'G4', 'B4', 'C5', 'G4', 'E4', 'D4']) {\n    // Keep the waveform running between notes; hard key cuts can click.\n    pce.noteOn(0, note);\n    await beat(0.5);\n  }\n});\n\n// Uploading a waveform stops its channel. Channels 4/5 can also generate noise.\n"
  },
  {
    "path": "/examples/opl/opl-live-operators.js",
    "name": "opl-live-operators",
    "data": "// Adjust OP1's total level while a note is held. No retrigger is needed.\n// TL: 0 = loudest, 63 = quietest. Operator indices are 0-based.\nsetBpm(100);\nopl.setPreset(0, OPL_PRESETS.organ);\nopl.setAlgo(0, 0, 2); // OP1 modulates OP2; feedback belongs to OP1.\n\nliveLoop('opl-timbre', async () => {\n  opl.noteOn(0, 'C4');\n  await tween({beats: 2}, progress => opl.setOperator(0, 0, {\n    tl: Math.round(50 - 34 * progress),\n  }));\n  await tween({beats: 2}, progress => opl.setOperator(0, 0, {\n    tl: Math.round(16 + 34 * progress),\n  }));\n  opl.keyOff(0);\n  await beat(1);\n});\n"
  },
  {
    "path": "/examples/opl/opl-melody.js",
    "name": "opl-melody",
    "data": "// Works in all OPL modes: OPL, OPL2, Y8950 FM and OPL3.\nsetBpm(112);\nopl.setPreset(0, OPL_PRESETS.bell);\nopl.setPreset(1, OPL_PRESETS.organ);\n\nliveLoop('opl-duet', async () => {\n  for (const [lead, bass] of [['C4', 'C3'], ['E4', 'C3'], ['G4', 'G2'], ['B4', 'G2']]) {\n    opl.noteOn(0, lead);\n    opl.noteOn(1, bass);\n    await beat(0.7);\n    opl.keyOff(0);\n    opl.keyOff(1);\n    await beat(0.3);\n  }\n});\n"
  },
  {
    "path": "/examples/opl/opl-rhythm.js",
    "name": "opl-rhythm",
    "data": "// All OPL models: rhythm reuses the operators of physical channels 6..8.\n// Prepare those voices while rhythm mode is off, then trigger individual gates.\nsetBpm(110);\nopl.setRhythm({enabled: false});\nfor (const channel of [6, 7, 8]) {\n  opl.setPreset(channel, OPL_PRESETS.organ);\n  opl.setNote(channel, channel === 6 ? 'C2' : 'G3');\n  for (const operator of [0, 1]) {\n    opl.setOperator(channel, operator, {tl: 20, ar: 15, dr: 9, sl: 12, rr: 10, egt: false});\n  }\n}\nopl.setRhythm({enabled: true});\n\nliveLoop('opl-rhythm', async () => {\n  for (let step = 0; step < 8; step++) {\n    const drum = step % 4 === 0 ? 'bassDrum' : step % 4 === 2 ? 'snare' : 'hiHat';\n    opl.setRhythm({[drum]: true});\n    await beat(0.12);\n    opl.setRhythm({[drum]: false});\n    await beat(0.38);\n  }\n});\n"
  },
  {
    "path": "/examples/opl/opl3-four-operators.js",
    "name": "opl3-four-operators",
    "data": "// OPL3: CH0 + CH3 form one four-operator voice; only CH0 receives notes.\nsetBpm(100);\nopl.setPreset(0, OPL_PRESETS['four-op-bell']);\n\nliveLoop('opl3-algorithms', async () => {\n  for (const algorithm of [0, 1, 2, 3]) {\n    opl.setAlgo(0, algorithm, 2);\n    for (const note of ['C4', 'E4', 'G4']) {\n      opl.noteOn(0, note);\n      await beat(0.6);\n      opl.keyOff(0);\n      await beat(0.2);\n    }\n  }\n});\n\n// setFourOp(0, false) returns physical CH3 to an independent two-op voice.\n"
  },
  {
    "path": "/examples/opl/opl3-stereo.js",
    "name": "opl3-stereo",
    "data": "// OPL3 channel outputs are routed left / right, rather than a continuous pan.\nsetBpm(120);\nopl.setPreset(0, OPL_PRESETS.bell);\nopl.setPreset(9, OPL_PRESETS.bell);\nopl.setPan(0, true, false);\nopl.setPan(9, false, true);\n\nliveLoop('opl3-stereo', async () => {\n  for (const [channel, note] of [[0, 'C4'], [9, 'E4'], [0, 'G4'], [9, 'C5']]) {\n    opl.noteOn(channel, note);\n    await beat(0.6);\n    opl.keyOff(channel);\n    await beat(0.4);\n  }\n});\n"
  }
